const Motion={mod:p=>((p%41)+41)%41,bounds:[0,13,24,34],phase:p=>{p=Motion.mod(p);return p<13?0:p<24?1:p<34?2:3},
 initial:()=>({eye:0,body:0,target:0,stage:0,mode:'click',moving:false,blinkAge:Infinity,jump:null,clicks:0,blinks:0,cycles:0,bodyFrom:0,bodyTo:0,bodyAge:0,bodyMs:0,bodyKind:'regular'}),
 follow:(s,to,ms,kind='regular')=>{s.bodyKind=kind;s.bodyFrom=s.body;s.bodyTo=to;s.bodyAge=0;s.bodyMs=Math.max(ms,1)},
 next:s=>{s={...s};if(s.jump!==null){s.eye=s.jump;s.jump=null;s.moving=false}if(s.mode==='always')s.stage=Motion.phase(s.eye);s.stage=(s.stage+1)%4;let d=Motion.mod(Motion.bounds[s.stage]-Motion.mod(s.eye));if(d<.0001)d=41;s.target=s.eye+d;s.clicks++;s.moving=true;
 if(s.stage===3){s.blinkAge=0;s.blinks++;s.jump=s.target;s.moving=false;Motion.follow(s,s.target,240,'blink')}else Motion.follow(s,s.target,Math.max((s.target-s.body)/.072,1));return s},
 mode:(s,mode)=>{s={...s};if(mode===s.mode)return s;if(mode==='click'&&s.jump===null&&!(s.blinkAge<240&&s.bodyKind==='blink')){const p=Motion.mod(s.eye),b=[13,24,34,41].find(b=>b>p+.000001)||41;s.target=s.eye+b-p;s.stage=b===41?0:Motion.bounds.indexOf(b);s.moving=true;Motion.follow(s,s.target,Math.max((s.target-s.body)/.072,1))}s.mode=mode;return s},
 tick:(s,dt)=>{s={...s};const old=s.eye;if(s.mode==='always'&&s.bodyKind==='regular')s.body+=Math.max(0,Math.min(s.eye-s.body,dt*.144));const wasBlink=s.blinkAge<240;s.blinkAge+=dt;
 if(s.jump!==null&&s.blinkAge>=120){s.eye=s.jump;s.jump=null;s.moving=false}
 if(s.bodyAge<s.bodyMs&&(s.mode==='click'||s.bodyKind==='blink')){s.bodyAge=Math.min(s.bodyMs,s.bodyAge+dt);const u=s.bodyAge/s.bodyMs;s.body=s.bodyFrom+(s.bodyTo-s.bodyFrom)*u}
 if(s.mode==='always'){
   if(!wasBlink){const before=s.eye;s.eye+=dt*.072;const cross=Math.floor((s.eye+17.000001)/41)>Math.floor((before+17.000001)/41);if(cross){s.eye=Math.floor(before/41)*41+24;s.target=s.eye+10;s.stage=3;s.blinks++;s.blinkAge=0;s.jump=s.target;Motion.follow(s,s.target,240,'blink')}else{if(s.bodyKind==='blink'&&s.blinkAge>=240)s.bodyKind='regular';s.body+=Math.max(0,Math.min(s.eye-s.body,dt*.144));s.bodyAge=s.bodyMs;s.stage=Motion.phase(s.eye)}}
 }else if(s.moving){s.eye=Math.min(s.target,s.eye+dt*.072);if(s.eye>=s.target-.00001){s.eye=s.target;s.moving=false}}
 s.cycles+=Math.max(0,Math.floor((s.eye+.000001)/41)-Math.floor((old+.000001)/41));return s},
 closure:s=>s.blinkAge<240?.5-.5*Math.cos(2*Math.PI*s.blinkAge/240):0};

function socket(c,i){c.beginPath();if(i===0){c.moveTo(600,469);c.bezierCurveTo(623,471,646,472,654,476);c.bezierCurveTo(663,480,666,484,664,486);c.bezierCurveTo(648,489,630,490,621,486);c.bezierCurveTo(611,480,605,475,600,469)}else{c.moveTo(776,467);c.bezierCurveTo(793,460,819,455,838,451);c.bezierCurveTo(833,465,829,471,817,474);c.bezierCurveTo(801,479,788,480,774,478);c.lineTo(776,467)}c.closePath()}
function eyes(p,blink){sc.clearRect(0,0,1419,1108);sc.drawImage(base,0,0);const [dx,dy]=interpolate(keys,p);for(let i=0;i<2;i++){const f=Motion.mod(p),w=f>=13&&f<=24?(f-13)/11:f>24&&f<34?(34-f)/10:0,cx=(i===0?652:818)+dx*(i===0?.65:1)+(i===0?-12*w:0),cy=(i===0?476:465)+dy;sc.save();socket(sc,i);sc.clip();sc.beginPath();sc.ellipse(cx,cy,15,17,0,0,Math.PI*2);sc.fillStyle='#652d2d';sc.fill();sc.lineWidth=2;sc.strokeStyle='#25181a';sc.stroke();sc.beginPath();sc.ellipse(cx,cy-1,7,11,0,0,Math.PI*2);sc.fillStyle='#130e11';sc.fill();sc.beginPath();sc.ellipse(cx-4,cy-5,2,3,0,0,Math.PI*2);sc.fillStyle='#dfcac7';sc.fill();if(blink>0){const xl=i===0?590:765,xr=i===0?680:847,yl=(i===0?463:466)+blink*(i===0?33:25),yr=(i===0?473:447)+blink*(i===0?33:30);sc.beginPath();sc.moveTo(xl,430);sc.lineTo(xr,430);sc.lineTo(xr,yr);sc.lineTo(xl,yl);sc.closePath();sc.fillStyle=i===0?'#a19595':'#ecdcd4';sc.fill();sc.beginPath();sc.moveTo(xl,yl);sc.lineTo(xr,yr);sc.strokeStyle='#251d21';sc.lineWidth=3;sc.stroke()}sc.restore()}tc.clearRect(0,0,512,400);tc.drawImage(sprite,0,0,512,400)}
